UPDATE products SET spec_json = json_set(spec_json, '$.detail', json('{"enabled":true,"slug":"root-control-gallon-pot","title":"Root Control Pot & Gallon Nursery Pot Wholesale | GreenSmart","metaDescription":"Root control pot & gallon nursery pot wholesale from China — air-pruning design, 1–10 gallon, MOQ 500 pcs, BPA-free PP, UV stable. FOB Shenzhen.","h1":"Root Control Pot & Gallon Nursery Pot","intro":"Air-pruning side walls prevent root circling and produce a dense, fibrous root system. The standard growing container for commercial nurseries and serious home growers across Southeast Asia.","points":["Air-pruning holes on sides and base — prevents root spiralling","1 gallon to 10 gallon range in stock","BPA-free, food-safe PP resin","UV-stabilized for outdoor nursery use in tropical climates","Stackable when empty — reduces warehouse and freight CBM"],"ctaPrimary":"Request Quote","ctaWhatsapp":"WhatsApp Sales","quickSpecs":[["MOQ","From 500 pcs"],["Lead Time","20–30 days"],["FOB Port","Shenzhen / Guangzhou"],["Sample","$8–15, refundable"]],"image":"product-stackable-seedling.jpg","imageAlt":"Root control gallon nursery pot wholesale","specsTitle":"Size & specification table","specs":[["Size","1 gal / 2 gal / 3 gal / 5 gal / 7 gal / 10 gal"],["Diameter range","ø15 cm – ø35 cm"],["Height range","14 cm – 32 cm"],["Material","BPA-free PP, UV-stabilized, food-safe grade"],["Wall type","Perforated / mesh sides for air pruning"],["Colors","Black (standard), dark green, brown, white"],["MOQ","500 pcs per size/color"],["Mixed LCL","Multiple sizes in one shipment accepted from 1 CBM"],["Certifications","BPA-free test report available; Form E (RCEP) on request"]],"buyerTitle":"Best-fit buyers","buyerTags":["Commercial nurseries VN/ID","Fruit tree farms","Flower exporters TH","Vegetable seedling distributors","Agri-supply wholesalers","Home grower retail chains"],"whyTitle":"Why air-pruning matters in SEA","whyItems":[["Tropical heat","roots grow faster in warm climates — air pruning prevents pot-bound root spiral more effectively than solid-wall pots."],["Transplant success","air-pruned root balls transplant with far less shock — critical for commercial growers who move plants multiple times."],["Water drainage","perforated walls prevent waterlogging in high-rainfall regions (Vietnam, Indonesia rainy season)."]],"galleryTitle":"Size Range & Application Gallery","galleryNote":"Detailed size photos and application shots are included in our sample pack — request yours on WhatsApp.","gallery":[{"image":"product-stackable-seedling-2.jpg","caption":"Air-pruning side panels · detail"},{"image":"product-stackable-seedling.jpg","caption":"Planted application · in use"}],"faqTitle":"Common buyer questions","faq":[["Solid vs mesh sides?","We supply both. Mesh/perforated = air pruning. Solid = standard nursery use. Same gallon sizes available in both styles."],["UV lifespan?","UV-stabilized PP rated for 2–3 outdoor seasons in tropical climates."],["Can we mix sizes in one order?","Yes — minimum 500 pcs total, can be distributed across up to 4 sizes."],["RCEP Form E available?","Yes — we are a registered RCEP Form E issuer. Reduces import duty to 0–5% for Vietnam and Indonesia."]],"shippingTitle":"Freight & export notes","shipping":["Stackable when empty — 500 pcs 3-gal pots fit approx. 1.8 CBM (vs 4+ CBM for non-stackable).","Main export routes: FOB Shenzhen → Cat Lai (VN) 6 days; → Tanjung Priok (ID) 9 days; → Laem Chabang (TH) 8 days.","HS 3926.90 — RCEP preferential rate applies for VN, TH, ID, MY, SG."],"moqLadder":["500-1499 pcs: standard sizes and colors, up to 4 sizes mixed","1500-3999 pcs: full gallon range mix with carton marks","4000+ pcs: private label marks and tailored container loading"],"leadTime":["Sampling: 5-8 days for standard gallon sizes","Bulk order: 20-30 days after deposit and quantity lock","Peak season buffer: reserve 2 weeks for logistics slots"],"related":["self-watering-double-layer","transparent-orchid-pot","creative-shaped-planter"],"languages":["en","vi","th","id"],"translations":{"vi":{"title":"Chau Kiem Soat Re & Chau Gallon Gia Si | GreenSmart","metaDescription":"Chau kiem soat re va chau gallon uom cay gia si tu Trung Quoc — thanh air-pruning, 1-10 gallon, MOQ 500 cai, PP khong BPA, chong UV. FOB Shenzhen.","h1":"Chau Kiem Soat Re & Chau Gallon Uom Cay","intro":"Thanh ben air-pruning chong re xoan va tao bo re day, nhieu re to. Chau trong tieu chuan cho vuon uom thuong mai va nguoi trong chuyen nghiep khap Dong Nam A.","points":["Lo air-pruning o thanh va day — chong re xoan vong","Du kich thuoc tu 1 gallon den 10 gallon co san","Nhua PP khong BPA, dat chuan an toan thuc pham","On dinh UV cho vuon uom ngoai troi khi hau nhiet doi","Xep chong khi rong — giam CBM kho va van chuyen"],"quickSpecs":[["MOQ","Tu 500 cai"],["Thoi gian giao","20-30 ngay"],["Cang FOB","Shenzhen / Guangzhou"],["Hang mau","$8-15, hoan phi"]],"specsTitle":"Bang kich thuoc va thong so","specs":[["Kich thuoc","1 gal / 2 gal / 3 gal / 5 gal / 7 gal / 10 gal"],["Duong kinh","ø15 cm - ø35 cm"],["Chieu cao","14 cm - 32 cm"],["Vat lieu","PP khong BPA, on dinh UV, chuan an toan thuc pham"],["Kieu thanh","Thanh duc lo / luoi cho air pruning"],["Mau sac","Den (tieu chuan), xanh dam, nau, trang"],["MOQ","500 cai moi size/mau"],["Tron LCL","Nhieu size trong mot lo hang, tu 1 CBM"],["Chung nhan","Co bao cao khong BPA; Form E (RCEP) theo yeu cau"]],"buyerTitle":"Nguoi mua phu hop nhat","buyerTags":["Vuon uom thuong mai VN/ID","Trang trai cay an qua","Nha xuat khau hoa TH","Nha phan phoi cay giong rau","Ban si vat tu nong nghiep","Chuoi ban le nguoi trong tai nha"],"whyTitle":"Vi sao air-pruning quan trong o Dong Nam A","whyItems":[["Nong nhiet doi","re phat trien nhanh trong khi hau nong — air pruning chong re xoan hieu qua hon chau thanh kin."],["Ty le song khi chuyen cay","bo re qua air-pruning it soc hon nhieu khi chuyen chau — quan trong voi nguoi trong thuong mai."],["Thoat nuoc","thanh duc lo chong ung nuoc o vung mua nhieu (mua mua Viet Nam, Indonesia)."]],"galleryTitle":"Dai kich thuoc va ung dung","galleryNote":"Them anh kich thuoc va ung dung se gui kem goi hang mau.","faq":[["Thanh kin hay thanh luoi?","Co ca hai. Luoi/duc lo = air pruning. Kin = vuon uom tieu chuan. Cung size gallon cho ca hai kieu."],["Tuoi tho UV?","PP on dinh UV chiu duoc 2-3 mua ngoai troi khi hau nhiet doi."],["Tron size trong mot don duoc khong?","Duoc — toi thieu 500 cai tong, chia toi da 4 size."],["Co Form E RCEP khong?","Co — chung toi la don vi phat hanh Form E RCEP. Giam thue nhap ve 0-5% cho Viet Nam va Indonesia."]],"shipping":["Xep chong khi rong — 500 chau 3 gal chi khoang 1,8 CBM (so voi 4+ CBM neu khong xep chong).","Tuyen chinh: FOB Shenzhen → Cat Lai (VN) 6 ngay; → Tanjung Priok (ID) 9 ngay; → Laem Chabang (TH) 8 ngay.","HS 3926.90 — thue uu dai RCEP ap dung cho VN, TH, ID, MY, SG."],"ctaPrimary":"Yeu cau bao gia","ctaWhatsapp":"WhatsApp ban hang","moqLadder":["500-1499 cai: size va mau tieu chuan, tron toi da 4 size","1500-3999 cai: tron du dai gallon kem ky hieu thung","4000+ cai: nhan rieng va xep container theo yeu cau"],"leadTime":["Lam mau: 5-8 ngay cho size gallon tieu chuan","Don lon: 20-30 ngay sau dat coc va chot so luong","Mua cao diem: du phong 2 tuan cho lich van chuyen"]},"th":{"title":"กระถางควบคุมราก & กระถางแกลลอนราคาส่ง | GreenSmart","metaDescription":"กระถางควบคุมรากและกระถางแกลลอนเพาะชำราคาส่งจากจีน — ผนัง air-pruning 1-10 แกลลอน MOQ 500 ชิ้น PP ปลอด BPA ทน UV FOB เซินเจิ้น","h1":"กระถางควบคุมราก & กระถางแกลลอนเพาะชำ","intro":"ผนังข้าง air-pruning กันรากขดและสร้างระบบรากแน่นแบบเส้นใย ภาชนะปลูกมาตรฐานของเรือนเพาะชำเชิงพาณิชย์และผู้ปลูกจริงจังทั่วเอเชียตะวันออกเฉียงใต้","points":["รู air-pruning ที่ผนังและก้น — กันรากขดวน","มีครบ 1 แกลลอนถึง 10 แกลลอนพร้อมส่ง","เรซิน PP ปลอด BPA เกรดสัมผัสอาหาร","ทน UV สำหรับเรือนเพาะกลางแจ้งภูมิอากาศร้อนชื้น","ซ้อนได้เมื่อว่าง — ลด CBM คลังและค่าขนส่ง"],"quickSpecs":[["MOQ","ตั้งแต่ 500 ชิ้น"],["ระยะเวลาผลิต","20-30 วัน"],["ท